package com.musicplaylist.controller;
import com.musicplaylist.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/playlist") public class PlaylistViewServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{Integer uid=Auth.userId(q);if(uid==null){p.sendRedirect(q.getContextPath()+"/login");return;}try{int id=Integer.parseInt(q.getParameter("id"));try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("SELECT pl.name,so.id,so.title,so.artist,so.album FROM playlists pl LEFT JOIN playlist_songs ps ON pl.id=ps.playlist_id LEFT JOIN songs so ON so.id=ps.song_id WHERE pl.id=? AND pl.user_id=?")){s.setInt(1,id);s.setInt(2,uid);List<Map<String,Object>> songs=new ArrayList<>();String name=null;try(ResultSet r=s.executeQuery()){while(r.next()){name=r.getString(1);if(r.getObject(2)!=null){Map<String,Object>m=new HashMap<>();m.put("id",r.getInt(2));m.put("title",r.getString(3));m.put("artist",r.getString(4));m.put("album",r.getString(5));songs.add(m);}}}if(name==null){p.sendError(404);return;}q.setAttribute("playlistId",id);q.setAttribute("playlistName",name);q.setAttribute("songs",songs);q.getRequestDispatcher("/playlist.jsp").forward(q,p);}}catch(NumberFormatException x){p.sendError(400);}catch(SQLException x){throw new ServletException(x);}}}